// Simula una consulta a un sistema ERP
const consulta = $input.item.json.query || "general";

const inventario = {
  "producto A": { stock: 50, precio: 150.00 },
  "producto B": { stock: 12, precio: 320.50 },
  "producto C": { stock: 0, precio: 75.00 }
};

// Busca si el query coincide con algún producto
let resultado = inventario[consulta.toLowerCase()];
if (!resultado) {
  resultado = { mensaje: "Producto no encontrado en el sistema interno." };
}

return [{ json: resultado }];

// Paso 1: Capturar la salida completa del Agente para el Execution Log (Observabilidad)
const fullOutput = $input.item.json;
console.log("=== REPORTE DE OBSERVABILIDAD HUMANA (EXECUTION LOG) ===");
console.log("Iteraciones usadas:", fullOutput.intermediateSteps?.length || 0);
console.log("Herramientas llamadas:", fullOutput.toolCalls || "Ninguna");
console.log("Respuesta cruda:", fullOutput.output);

// Paso 2: Extraer SOLO la respuesta textual para enviarla al chat
const agentReply = fullOutput.output || "Lo siento, no pude procesar tu solicitud.";

// Paso 3: Devolver el texto limpio. El Chat Trigger enviará esto al usuario.
return [{ json: { response: agentReply } }];
